namespace DonationHub.Application.Features.Dashboard.GetSummary;

public sealed record GetDashboardSummaryQuery : IRequest<Result<DashboardSummaryDto>>;

public sealed class GetDashboardSummaryQueryHandler(IReadDbContext db, ICacheService cache)
    : IRequestHandler<GetDashboardSummaryQuery, Result<DashboardSummaryDto>>
{
    public async Task<Result<DashboardSummaryDto>> Handle(GetDashboardSummaryQuery request, CancellationToken ct)
    {
        var summary = await cache.GetOrCreateAsync(     // امتداد cache-aside من Sprint 3
            DashboardCacheKeys.Summary,
            LoadAsync,                                  // لا نصل للـ DB إلا عند غياب المفتاح
            CacheProfile.Dashboard,
            ct);

        return summary;                                 // تحويل ضمني إلى Result<T> (Sprint 2)
    }

    private async Task<DashboardSummaryDto> LoadAsync(CancellationToken ct)
    {
        var succeeded = db.Donations.Where(d => d.Status == DonationStatus.Succeeded);

        // SELECT COALESCE(SUM([Amount]), 0) ... — الـ cast إلى decimal? يحمي من SUM على مجموعة فارغة
        var totalRaised = await succeeded.SumAsync(d => (decimal?)d.Amount, ct) ?? 0m;
        var donationsCount = await succeeded.CountAsync(ct);
        var distinctDonors = await succeeded.Select(d => d.DonorUserId).Distinct().CountAsync(ct);

        // SELECT [Status], COUNT(*) FROM [Campaigns] WHERE [IsDeleted] = 0 GROUP BY [Status]
        var byStatus = await db.Campaigns
            .GroupBy(c => c.Status)
            .Select(g => new { Status = g.Key, Count = g.Count() })
            .ToDictionaryAsync(x => x.Status, x => x.Count, ct);

        return new DashboardSummaryDto(
            totalRaised,
            donationsCount,
            distinctDonors,
            byStatus.GetValueOrDefault(CampaignStatus.Active),
            byStatus.GetValueOrDefault(CampaignStatus.Completed),
            byStatus.GetValueOrDefault(CampaignStatus.Expired));
    }
}

namespace DonationHub.Application.Features.Dashboard.GetTopCampaigns;

public sealed record GetTopCampaignsQuery(int Count = 5) : IRequest<Result<List<TopCampaignDto>>>;

public sealed class GetTopCampaignsQueryValidator : AbstractValidator<GetTopCampaignsQuery>
{
    public GetTopCampaignsQueryValidator() =>
        RuleFor(x => x.Count).InclusiveBetween(1, 50);   // لا نسمح بـ count=100000
}

public sealed class GetTopCampaignsQueryHandler(IReadDbContext db, ICacheService cache)
    : IRequestHandler<GetTopCampaignsQuery, Result<List<TopCampaignDto>>>
{
    public async Task<Result<List<TopCampaignDto>>> Handle(GetTopCampaignsQuery request, CancellationToken ct)
    {
        var top = await cache.GetOrCreateAsync(
            DashboardCacheKeys.TopCampaigns(request.Count),
            token => db.Campaigns
                .OrderByDescending(c => c.RaisedAmount)
                .ThenBy(c => c.CreatedAt)                // ترتيب ثابت عند التعادل
                .Take(request.Count)                     // SELECT TOP(@count)
                .Select(c => new TopCampaignDto(         // projection: 7 أعمدة فقط، بدون الأوصاف الطويلة
                    c.Id,
                    c.TitleEn,
                    c.TitleAr,
                    c.Status,
                    c.GoalAmount,
                    c.RaisedAmount,
                    Math.Round(c.RaisedAmount * 100 / c.GoalAmount, 2)))   // GoalAmount > 0 قاعدة مجال
                .ToListAsync(token),
            CacheProfile.Dashboard,
            ct);

        return top;
    }
}

namespace DonationHub.Application.Features.Dashboard.GetDonationsOverTime;

public sealed record GetDonationsOverTimeQuery(DateOnly From, DateOnly To)
    : IRequest<Result<List<DailyDonationsDto>>>;

public sealed class GetDonationsOverTimeQueryValidator : AbstractValidator<GetDonationsOverTimeQuery>
{
    public GetDonationsOverTimeQueryValidator()
    {
        RuleFor(x => x.From).NotEmpty();                // default(DateOnly) يعني أن المعامل لم يُرسل
        RuleFor(x => x.To).NotEmpty()
            .GreaterThanOrEqualTo(x => x.From);
        RuleFor(x => x)
            .Must(x => x.To.DayNumber - x.From.DayNumber <= 366)
            .WithMessage("The date range cannot exceed 366 days.");
    }
}

public sealed class GetDonationsOverTimeQueryHandler(IReadDbContext db, ICacheService cache)
    : IRequestHandler<GetDonationsOverTimeQuery, Result<List<DailyDonationsDto>>>
{
    public async Task<Result<List<DailyDonationsDto>>> Handle(GetDonationsOverTimeQuery request, CancellationToken ct)
    {
        var days = await cache.GetOrCreateAsync(
            DashboardCacheKeys.DonationsOverTime(request.From, request.To),
            token => LoadAsync(request.From, request.To, token),
            CacheProfile.Dashboard,
            ct);

        return days;
    }

    private async Task<List<DailyDonationsDto>> LoadAsync(DateOnly from, DateOnly to, CancellationToken ct)
    {
        // نطاق نصف مفتوح [start, endExclusive) حتى لا نفقد تبرعات اليوم الأخير بعد 00:00
        var start = from.ToDateTime(TimeOnly.MinValue, DateTimeKind.Utc);
        var endExclusive = to.AddDays(1).ToDateTime(TimeOnly.MinValue, DateTimeKind.Utc);

        var rows = await db.Donations
            .Where(d => d.Status == DonationStatus.Succeeded
                        && d.CreatedAt >= start
                        && d.CreatedAt < endExclusive)
            .GroupBy(d => d.CreatedAt.Date)              // CONVERT(date, [CreatedAt])
            .Select(g => new { Day = g.Key, Total = g.Sum(d => d.Amount), Count = g.Count() })
            .OrderBy(x => x.Day)
            .ToListAsync(ct);

        // SQL لا يُرجع الأيام التي ليس فيها تبرعات؛ نملأ الفراغات بأصفار في الذاكرة (بضع عشرات من الأسطر فقط)
        var byDay = rows.ToDictionary(r => DateOnly.FromDateTime(r.Day));
        var result = new List<DailyDonationsDto>();
        for (var day = from; day <= to; day = day.AddDays(1))
        {
            result.Add(byDay.TryGetValue(day, out var row)
                ? new DailyDonationsDto(day, row.Total, row.Count)
                : new DailyDonationsDto(day, 0m, 0));
        }
        return result;
    }
}

