public static class AdminErrors
{
    public static readonly Error UserNotFound =
        new("User.NotFound", "The user was not found.", ErrorType.NotFound);                  // 404

    public static readonly Error StaffNotFound =
        new("Staff.NotFound", "The staff user was not found.", ErrorType.NotFound);           // 404

    public static readonly Error CannotDeactivateSelf =
        new("Admin.CannotDeactivateSelf", "You cannot deactivate or demote your own account.",
            ErrorType.UnprocessableEntity);                                                   // 422

    public static readonly Error LastActiveAdmin =
        new("Admin.LastActiveAdmin", "The last active Admin cannot be deactivated or demoted.",
            ErrorType.Conflict);                                                              // 409
}

namespace DonationHub.Application.Features.Admin;

internal static class AdminAccountRules
{
    // تُستدعى قبل أي عملية «تسحب» صلاحية Admin فعّالة: تعطيل، حذف موظف، أو تخفيض الدور
    public static async Task<Error?> CheckCanRemoveAccessAsync(
        ManagedUser target, Guid currentUserId, IUserAdministration users, CancellationToken ct)
    {
        if (target.Id == currentUserId)
            return AdminErrors.CannotDeactivateSelf;

        var targetIsActiveAdmin = target.IsActive && target.Roles.Contains(Roles.Admin);
        if (targetIsActiveAdmin && await users.CountActiveAdminsAsync(ct) <= 1)
            return AdminErrors.LastActiveAdmin;

        return null;
    }
}

namespace DonationHub.Application.Features.Admin.Users.SetUserStatus;

public sealed record SetUserStatusCommand(Guid UserId, bool IsActive) : IRequest<Result>;

public sealed class SetUserStatusCommandHandler(IUserAdministration users, ICurrentUser currentUser)
    : IRequestHandler<SetUserStatusCommand, Result>
{
    public async Task<Result> Handle(SetUserStatusCommand request, CancellationToken ct)
    {
        var user = await users.FindAsync(request.UserId, ct);
        if (user is null)
            return Result.Failure(AdminErrors.UserNotFound);

        if (user.IsActive == request.IsActive)
            return Result.Success();                     // idempotent: لا تغيير

        if (!request.IsActive)
        {
            var error = await AdminAccountRules.CheckCanRemoveAccessAsync(user, currentUser.UserId, users, ct);
            if (error is not null)
                return Result.Failure(error);
        }

        await users.SetActiveAsync(user.Id, request.IsActive, ct);
        return Result.Success();
    }
}

