public sealed record UpdateStaffCommand(Guid UserId, string FullName, string Role) : IRequest<Result>;

public sealed class UpdateStaffCommandValidator : AbstractValidator<UpdateStaffCommand>
{
    public UpdateStaffCommandValidator()
    {
        RuleFor(x => x.FullName).NotEmpty().MaximumLength(100);
        RuleFor(x => x.Role).Must(r => r is Roles.Admin or Roles.CampaignManager)
            .WithMessage("Role must be Admin or CampaignManager.");
    }
}

public sealed class UpdateStaffCommandHandler(IUserAdministration users, ICurrentUser currentUser)
    : IRequestHandler<UpdateStaffCommand, Result>
{
    public async Task<Result> Handle(UpdateStaffCommand request, CancellationToken ct)
    {
        var user = await users.FindAsync(request.UserId, ct);
        if (user is null || !user.Roles.Any(r => r is Roles.Admin or Roles.CampaignManager))
            return Result.Failure(AdminErrors.StaffNotFound);   // المتبرّع ليس «موظفًا»

        var isDemotion = user.Roles.Contains(Roles.Admin) && request.Role != Roles.Admin;
        if (isDemotion)
        {
            var error = await AdminAccountRules.CheckCanRemoveAccessAsync(user, currentUser.UserId, users, ct);
            if (error is not null)
                return Result.Failure(error);
        }

        await users.UpdateStaffAsync(user.Id, request.FullName.Trim(), request.Role, ct);
        return Result.Success();
    }
}

