namespace DonationHub.Infrastructure.Identity;

internal sealed class UserAdministration(AppDbContext db, UserManager<ApplicationUser> userManager)
    : IUserAdministration
{
    private static readonly string[] StaffRoles = [Roles.Admin, Roles.CampaignManager];

    public async Task<PagedList<AdminUserDto>> GetUsersAsync(UserListFilter filter, CancellationToken ct)
    {
        IQueryable<ApplicationUser> query = db.Users.AsNoTracking();

        if (filter.StaffOnly)
            query = query.Where(u => db.UserRoles.Any(ur => ur.UserId == u.Id &&
                db.Roles.Any(r => r.Id == ur.RoleId && StaffRoles.Contains(r.Name!))));

        if (!string.IsNullOrWhiteSpace(filter.Role))
            query = query.Where(u => db.UserRoles.Any(ur => ur.UserId == u.Id &&
                db.Roles.Any(r => r.Id == ur.RoleId && r.Name == filter.Role)));

        if (!string.IsNullOrWhiteSpace(filter.Search))
        {
            var term = filter.Search.Trim();
            query = query.Where(u => u.FullName.Contains(term) || u.Email!.Contains(term));   // LIKE N'%term%'
        }

        var projected = query
            .OrderBy(u => u.FullName).ThenBy(u => u.Id)          // ترتيب فريد: شرط لترقيم صحيح ولـ split query
            .Select(u => new AdminUserDto(
                u.Id, u.FullName, u.Email!, u.IsActive, u.CreatedAt,
                (from ur in db.UserRoles
                 join r in db.Roles on ur.RoleId equals r.Id
                 where ur.UserId == u.Id
                 select r.Name!).ToList()))
            .AsSplitQuery();                                     // استعلام للمستخدمين + استعلام للأدوار

        // PagedList من Sprint 3: COUNT ثم Skip/Take داخل SQL على الـ IQueryable المُسقَط
        return await PagedList<AdminUserDto>.CreateAsync(projected, filter.Page, filter.PageSize, ct);
    }

    public async Task<ManagedUser?> FindAsync(Guid userId, CancellationToken ct)
    {
        var user = await userManager.FindByIdAsync(userId.ToString());
        if (user is null) return null;

        var roles = await userManager.GetRolesAsync(user);
        return new ManagedUser(user.Id, user.IsActive, roles.ToList());
    }

    public Task<int> CountActiveAdminsAsync(CancellationToken ct) =>
        (from u in db.Users
         join ur in db.UserRoles on u.Id equals ur.UserId
         join r in db.Roles on ur.RoleId equals r.Id
         where u.IsActive && r.Name == Roles.Admin
         select u.Id).Distinct().CountAsync(ct);

    public async Task SetActiveAsync(Guid userId, bool isActive, CancellationToken ct)
    {
        var user = await userManager.FindByIdAsync(userId.ToString())
                   ?? throw new InvalidOperationException($"User {userId} disappeared.");

        user.IsActive = isActive;
        EnsureSucceeded(await userManager.UpdateAsync(user));

        // تسجيل الدخول والتجديد يفحصان IsActive أصلًا (IDN-10)، فالمستخدم المعطَّل
        // لا يحصل على access token جديد. الـ token الحالي ينتهي خلال دقائق.
    }

    public async Task UpdateStaffAsync(Guid userId, string fullName, string role, CancellationToken ct)
    {
        var strategy = db.Database.CreateExecutionStrategy();   // ضروري مع EnableRetryOnFailure
        await strategy.ExecuteAsync(async () =>
        {
            await using var tx = await db.Database.BeginTransactionAsync(ct);

            var user = await userManager.FindByIdAsync(userId.ToString())
                       ?? throw new InvalidOperationException($"User {userId} disappeared.");
            user.FullName = fullName;
            EnsureSucceeded(await userManager.UpdateAsync(user));

            var currentStaffRoles = (await userManager.GetRolesAsync(user)).Intersect(StaffRoles).ToList();
            if (!currentStaffRoles.SequenceEqual(new[] { role }))
            {
                EnsureSucceeded(await userManager.RemoveFromRolesAsync(user, currentStaffRoles));
                EnsureSucceeded(await userManager.AddToRoleAsync(user, role));
            }

            await tx.CommitAsync(ct);                            // الاسم والدور يتغيّران معًا أو لا يتغيّران
        });
    }

    private static void EnsureSucceeded(IdentityResult result)
    {
        if (!result.Succeeded)   // غير متوقع → الـ global handler يُرجع 500 عام
            throw new InvalidOperationException(string.Join("; ", result.Errors.Select(e => e.Description)));
    }
}

