namespace DonationHub.UnitTests.Admin;

public sealed class SetUserStatusCommandHandlerTests
{
    private readonly Mock<IUserAdministration> _users = new();
    private readonly Mock<ICurrentUser> _currentUser = new();
    private readonly Guid _callerId = Guid.NewGuid();

    public SetUserStatusCommandHandlerTests() =>
        _currentUser.SetupGet(c => c.UserId).Returns(_callerId);

    private SetUserStatusCommandHandler CreateSut() => new(_users.Object, _currentUser.Object);

    private void GivenUser(Guid id, bool isActive, params string[] roles) =>
        _users.Setup(u => u.FindAsync(id, It.IsAny<CancellationToken>()))
              .ReturnsAsync(new ManagedUser(id, isActive, roles));

    [Fact]
    public async Task Admin_cannot_deactivate_themself()
    {
        GivenUser(_callerId, isActive: true, Roles.Admin);

        var result = await CreateSut().Handle(new SetUserStatusCommand(_callerId, false), CancellationToken.None);

        result.IsFailure.Should().BeTrue();
        result.Error.Should().Be(AdminErrors.CannotDeactivateSelf);
        _users.Verify(u => u.SetActiveAsync(It.IsAny<Guid>(), It.IsAny<bool>(), It.IsAny<CancellationToken>()),
            Times.Never);
    }

    [Fact]
    public async Task Last_active_admin_cannot_be_deactivated()
    {
        var otherAdmin = Guid.NewGuid();
        GivenUser(otherAdmin, isActive: true, Roles.Admin);
        _users.Setup(u => u.CountActiveAdminsAsync(It.IsAny<CancellationToken>())).ReturnsAsync(1);

        var result = await CreateSut().Handle(new SetUserStatusCommand(otherAdmin, false), CancellationToken.None);

        result.Error.Should().Be(AdminErrors.LastActiveAdmin);
        _users.Verify(u => u.SetActiveAsync(otherAdmin, false, It.IsAny<CancellationToken>()), Times.Never);
    }

    [Fact]
    public async Task Admin_can_be_deactivated_when_another_active_admin_exists()
    {
        var otherAdmin = Guid.NewGuid();
        GivenUser(otherAdmin, isActive: true, Roles.Admin);
        _users.Setup(u => u.CountActiveAdminsAsync(It.IsAny<CancellationToken>())).ReturnsAsync(2);

        var result = await CreateSut().Handle(new SetUserStatusCommand(otherAdmin, false), CancellationToken.None);

        result.IsSuccess.Should().BeTrue();
        _users.Verify(u => u.SetActiveAsync(otherAdmin, false, It.IsAny<CancellationToken>()), Times.Once);
    }

    [Fact]
    public async Task Donor_can_be_deactivated_without_counting_admins()
    {
        var donor = Guid.NewGuid();
        GivenUser(donor, isActive: true, Roles.Donor);

        var result = await CreateSut().Handle(new SetUserStatusCommand(donor, false), CancellationToken.None);

        result.IsSuccess.Should().BeTrue();
        _users.Verify(u => u.CountActiveAdminsAsync(It.IsAny<CancellationToken>()), Times.Never);
    }

    [Fact]
    public async Task Unknown_user_returns_not_found()
    {
        var result = await CreateSut().Handle(new SetUserStatusCommand(Guid.NewGuid(), false), CancellationToken.None);

        result.Error.Should().Be(AdminErrors.UserNotFound);
    }
}

