namespace DonationHub.Api.IntegrationTests.Admin;

[Collection(ApiCollection.Name)]                                     // نفس الـ factory المشتركة من Sprint 5
public sealed class DeactivatedUserLoginTests(DonationHubApiFactory factory)
{
    [Fact]
    public async Task Deactivated_user_cannot_log_in()
    {
        var client = factory.CreateClient();
        var email = $"donor-{Guid.NewGuid():N}@tests.local";
        client.UseToken(await client.RegisterAndLoginAsync(email));     // helpers من Sprint 5
        var donorId = (await client.GetFromJsonAsync<JsonElement>("/api/v1/auth/me")).GetProperty("id").GetGuid();

        client.UseToken(await client.LoginAsync(DonationHubApiFactory.AdminEmail, DonationHubApiFactory.AdminPassword));
        var patch = await client.PatchAsJsonAsync($"/api/v1/admin/users/{donorId}/status", new { isActive = false });
        patch.StatusCode.Should().Be(HttpStatusCode.NoContent);

        client.DefaultRequestHeaders.Authorization = null;
        var login = await client.PostAsJsonAsync("/api/v1/auth/login", new { email, password = "Donor#12345" });   // كلمة مرور RegisterAndLoginAsync الافتراضية

