public sealed class FileStorageHealthCheck(IOptions<FileStorageOptions> options) : IHealthCheck
{
    public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context, CancellationToken ct = default)
    {
        var root = options.Value.RootPath;
        var probe = Path.Combine(root, $".health-{Guid.NewGuid():N}.tmp");

        try
        {
            Directory.CreateDirectory(root);
            await File.WriteAllTextAsync(probe, "ok", ct);
            File.Delete(probe);
            return HealthCheckResult.Healthy("File storage is writable.");
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            // لا نُرجع المسار ولا رسالة الاستثناء في الاستجابة العامة؛ التفاصيل في الـ log فقط
            return new HealthCheckResult(context.Registration.FailureStatus,
                "File storage is not writable.", ex);
        }
    }
}

using System.Text.Json;
using DonationHub.Infrastructure.Health;
using Microsoft.AspNetCore.Diagnostics.HealthChecks;
using Microsoft.Extensions.Diagnostics.HealthChecks;

namespace DonationHub.Api.Health;

public static class HealthChecksSetup
{
    public const string ReadyTag = "ready";

    public static IServiceCollection AddDonationHubHealthChecks(this IServiceCollection services, IConfiguration config)
    {
        var sql = config.GetConnectionString("Default")
                  ?? throw new InvalidOperationException("ConnectionStrings:Default is missing.");
        var redis = config.GetConnectionString("Redis")
                    ?? throw new InvalidOperationException("ConnectionStrings:Redis is missing.");

        services.AddHealthChecks()
            .AddSqlServer(sql, name: "sqlserver", tags: [ReadyTag], timeout: TimeSpan.FromSeconds(5))
            .AddRedis(redis, name: "redis", tags: [ReadyTag], timeout: TimeSpan.FromSeconds(5))
            .AddCheck<FileStorageHealthCheck>("file-storage", tags: [ReadyTag]);

        return services;
    }

    public static WebApplication MapDonationHubHealthChecks(this WebApplication app)
    {
        app.MapHealthChecks("/health/live", new HealthCheckOptions
        {
            Predicate = _ => false,                          // liveness: no dependency checks
            ResponseWriter = WriteJsonAsync
        }).AllowAnonymous().DisableRateLimiting();

        app.MapHealthChecks("/health/ready", new HealthCheckOptions
        {
            Predicate = check => check.Tags.Contains(ReadyTag),
            ResponseWriter = WriteJsonAsync                  // 200 Healthy/Degraded, 503 Unhealthy
        }).AllowAnonymous().DisableRateLimiting();

        return app;
    }

    private static Task WriteJsonAsync(HttpContext context, HealthReport report)
    {
        var payload = new
        {
            status = report.Status.ToString(),
            totalDurationMs = Math.Round(report.TotalDuration.TotalMilliseconds, 1),
            checks = report.Entries.Select(e => new
            {
                name = e.Key,
                status = e.Value.Status.ToString(),
                durationMs = Math.Round(e.Value.Duration.TotalMilliseconds, 1),
                description = e.Value.Description
            })
        };

        return context.Response.WriteAsJsonAsync(payload);   // Content-Type: application/json
    }
}

